import { Component, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ApiService } from './api.service';
import { MessageService } from './message.service';
import { ManufacturerDto } from './models';

@Component({
  selector: 'app-manufacturer',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div class="big-title"><h2>Manufacturers</h2>
      <button id="gwt-debug-create-manufacturer" class="add-action" (click)="create()">Create</button></div>
    <table id="gwt-debug-manufacturers" class="grid">
      <thead><tr><th>ID</th><th>Name</th><th>Edit</th><th>Delete</th></tr></thead>
      <tbody>
        @for (m of items(); track m) {
          <tr><td>{{ m.id }}</td><td>{{ m.name }}</td>
            <td><button (click)="edit(m)">Edit</button></td>
            <td><button (click)="remove(m)">Delete</button></td></tr>
        }
      </tbody>
    </table>
    @if (editing(); as e) {
      <div class="glass" (click)="close()"></div>
      <div class="popup" id="gwt-debug-manufacturer-editor">
        <div><span>Name:</span> <input id="gwt-debug-manufacturer-input" type="text" [(ngModel)]="name"></div>
        <div><button id="gwt-debug-manufacturer-save" (click)="save()">Save</button>
          <button id="gwt-debug-manufacturer-close" (click)="close()">Close</button></div>
      </div>
    }`,
})
export class ManufacturerComponent implements OnInit {
  private api = inject(ApiService);
  private messages = inject(MessageService);
  items = signal<ManufacturerDto[]>([]);
  editing = signal<{ target: ManufacturerDto | null } | null>(null);
  name = '';

  ngOnInit(): void { this.api.run(this.api.getManufacturers(), l => this.items.set(l)); }

  create(): void { this.name = ''; this.editing.set({ target: null }); }
  edit(m: ManufacturerDto): void { this.name = m.name; this.editing.set({ target: m }); }
  close(): void { this.editing.set(null); }

  save(): void {
    const target = this.editing()?.target ?? null;
    const dto: ManufacturerDto = target ? { ...target, name: this.name } : { name: this.name, cars: [] };
    this.api.run(this.api.saveManufacturer(dto), saved => {
      this.messages.success('Manufacturer saved');
      this.items.update(l => target ? l.map(x => (x === target ? saved : x)) : [...l, saved]);
      this.close();
    });
  }

  remove(m: ManufacturerDto): void {
    if (!confirm('Are you sure you want to delete ' + m.name + '?')) { return; }
    this.api.run(this.api.deleteManufacturer(m.id as number), () =>
      this.items.update(l => l.filter(x => x !== m)));
  }
}
EOF
cat > rating.component.ts <<'EOF'
import { Component, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ApiService } from './api.service';
import { MessageService } from './message.service';
import { CarDto, RatingDto, carLabel } from './models';

@Component({
  selector: 'app-rating',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div class="big-title"><h2>Ratings</h2>
      <button id="gwt-debug-ratingCreate" class="add-action" (click)="create()">Create</button></div>
    <table id="gwt-debug-ratings" class="grid">
      <thead><tr><th>ID</th><th>Car</th><th>Rating</th><th>Delete</th></tr></thead>
      <tbody>
        @for (r of items(); track r) {
          <tr><td>{{ r.id }}</td><td>{{ label(r.car) }}</td><td>{{ r.rating }}</td>
            <td><button (click)="remove(r)">Delete</button></td></tr>
        }
      </tbody>
    </table>
    @if (showForm()) {
      <div class="glass" (click)="close()"></div>
      <div class="popup">
        <div><span>Car:</span>
          <select [(ngModel)]="car">
            @for (c of cars(); track c) { <option [ngValue]="c">{{ label(c) }}</option> }
          </select></div>
        <div><span>Your rating:</span>
          <input id="gwt-debug-ratingInput" type="number" maxlength="3" [(ngModel)]="rating"></div>
        <div><button id="gwt-debug-ratingSave" (click)="save()">Save</button>
          <button (click)="close()">Close</button></div>
      </div>
    }`,
})
export class RatingComponent implements OnInit {
  private api = inject(ApiService);
  private messages = inject(MessageService);
  items = signal<RatingDto[]>([]);
  cars = signal<CarDto[]>([]);
  showForm = signal(false);
  car: CarDto | null = null;
  rating: number | null = null;
  label = carLabel;

  ngOnInit(): void { this.api.run(this.api.getRatings(), l => this.items.set(l)); }

  create(): void {
    this.api.run(this.api.getCars(), cars => {
      this.cars.set(cars);
      this.car = cars[0] ?? null;
      this.rating = null;
      this.showForm.set(true);
    });
  }
  close(): void { this.showForm.set(false); }

  save(): void {
    const dto: RatingDto = { car: this.car, rating: this.rating };
    this.api.run(this.api.saveRating(dto), saved => {
      this.messages.success('Rating saved');
      this.items.update(l => [...l, saved]);
      this.close();
    });
  }

  remove(r: RatingDto): void {
    if (!confirm('Are you sure you want to delete this rating?')) { return; }
    this.api.run(this.api.deleteRating(r.id as number), () =>
      this.items.update(l => l.filter(x => x !== r)));
  }
}
EOF
